    // comparison of the number.
    fn state_of(id: ::sce_rust_runtime::StateId) -> Self::State {
        match id.0 {
            0 => ReassemblySlotState::Empty,
            1 => ReassemblySlotState::Receiving,
            2 => ReassemblySlotState::Complete,
            3 => ReassemblySlotState::TimedOut,
            4 => ReassemblySlotState::Aborted,
            _ => ::sce_rust_runtime::helpers::tables::row_missing(),
        }
    }

    fn history_of(id: ::sce_rust_runtime::HistoryId) -> Self::History {
        // No `<history>`, so no number names one.
        let _ = id;
        ::sce_rust_runtime::helpers::tables::row_missing()
    }

    fn event_of(id: ::sce_rust_runtime::EventId) -> Self::Event {
        match id.0 {
            0 => ReassemblySlotEvent::CodecError,
            1 => ReassemblySlotEvent::FragmentDrop,
            2 => ReassemblySlotEvent::FragmentLast,
            3 => ReassemblySlotEvent::FragmentMore,
            4 => ReassemblySlotEvent::FragmentOoo,
            5 => ReassemblySlotEvent::ReassemblyTimeout,
            6 => ReassemblySlotEvent::SlotEvict,
            7 => ReassemblySlotEvent::SlotRelease,
            8 => ReassemblySlotEvent::Null,
            _ => ::sce_rust_runtime::helpers::tables::row_missing(),
        }
    }

