    // methods (docs/adr/0064), so none of it is written here a second time.

    fn get_event_name(event: Self::Event) -> &'static str {
        match event {
            ReassemblySlotEvent::CodecError => "codec.error",
            ReassemblySlotEvent::FragmentDrop => "fragment.drop",
            ReassemblySlotEvent::FragmentLast => "fragment.last",
            ReassemblySlotEvent::FragmentMore => "fragment.more",
            ReassemblySlotEvent::FragmentOoo => "fragment.ooo",
            ReassemblySlotEvent::ReassemblyTimeout => "reassembly.timeout",
            ReassemblySlotEvent::SlotEvict => "slot.evict",
            ReassemblySlotEvent::SlotRelease => "slot.release",
            ReassemblySlotEvent::Null => "",
        }
    }

    fn get_event_from_name(name: &str) -> Option<Self::Event> {
        match name {
            "codec.error" => Some(ReassemblySlotEvent::CodecError),
            "fragment.drop" => Some(ReassemblySlotEvent::FragmentDrop),
            "fragment.last" => Some(ReassemblySlotEvent::FragmentLast),
            "fragment.more" => Some(ReassemblySlotEvent::FragmentMore),
            "fragment.ooo" => Some(ReassemblySlotEvent::FragmentOoo),
            "reassembly.timeout" => Some(ReassemblySlotEvent::ReassemblyTimeout),
            "slot.evict" => Some(ReassemblySlotEvent::SlotEvict),
            "slot.release" => Some(ReassemblySlotEvent::SlotRelease),
            _ => None,
        }
    }

    fn get_state_name(state: Self::State) -> &'static str {
        match state {
            ReassemblySlotState::Aborted => "Aborted",
            ReassemblySlotState::Complete => "Complete",
            ReassemblySlotState::Empty => "Empty",
            ReassemblySlotState::Receiving => "Receiving",
            ReassemblySlotState::TimedOut => "TimedOut",
        }
    }

    // The inverse of the table above, emitted from the same loop over the
    // document's states so the two age together. It is what lets a host turn a
    // recorded configuration back into the slice `enter_at` takes.
    fn get_state_from_name(name: &str) -> Option<Self::State> {
        match name {
            "Aborted" => Some(ReassemblySlotState::Aborted),
            "Complete" => Some(ReassemblySlotState::Complete),
            "Empty" => Some(ReassemblySlotState::Empty),
            "Receiving" => Some(ReassemblySlotState::Receiving),
            "TimedOut" => Some(ReassemblySlotState::TimedOut),
            _ => None,
        }
    }

    fn null_event() -> Self::Event {
        ReassemblySlotEvent::Null
    }

